import{_ as e,o as i,c as o,a6 as n}from"./chunks/framework.DNkVJs23.js";const w=JSON.parse('{"title":"Polityka prywatności","description":"Polityka prywatności — Sapphire Star Codex","frontmatter":{"description":"Polityka prywatności — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/pl/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/pl/privacy/"}],["meta",{"property":"og:title","content":"Polityka prywatności | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Polityka prywatności — Sapphire Star Codex"}]]},"headers":[],"relativePath":"pl/privacy/index.md","filePath":"pl/privacy/index.md"}'),r={name:"pl/privacy/index.md"};function t(p,a,c,z,y,s){return i(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="polityka-prywatnosci" tabindex="-1">Polityka prywatności <a class="header-anchor" href="#polityka-prywatnosci" aria-label="Permalink to &quot;Polityka prywatności&quot;">​</a></h1><p>Obowiązuje od 31 października 2026 r. Ostatnia aktualizacja tekstu źródłowego: 10 listopada 2026 r. Tłumaczenie: 14 listopada 2026 r.</p><p>Polityka dotyczy aplikacji Sapphire Star Codex na iOS, Android i HarmonyOS oraz tej witryny. Twórca: <strong>eurekaffeine (刘耀晨)</strong>. Kontakt: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Funkcje zależą od platformy; konto nie jest wymagane.</p><h2 id="dane-lokalne" tabindex="-1">Dane lokalne <a class="header-anchor" href="#dane-lokalne" aria-label="Permalink to &quot;Dane lokalne&quot;">​</a></h2><p>Aplikacja zapisuje na urządzeniu ustawienia gry, języka i wyglądu, historię wyszukiwania i stan nawigacji, ulubione, zapisane zestawy i ich nazwy oraz zapasy dekoracji, talizmanów i pancerzy. Dane służą funkcjom aplikacji i nie są przesyłane twórcy. Twórca nie prowadzi kont ani usługi synchronizacji w chmurze.</p><h2 id="uprawnienia-i-automatyczne-zbieranie" tabindex="-1">Uprawnienia i automatyczne zbieranie <a class="header-anchor" href="#uprawnienia-i-automatyczne-zbieranie" aria-label="Permalink to &quot;Uprawnienia i automatyczne zbieranie&quot;">​</a></h2><p>Aplikacja nie zawiera SDK reklamowych, śledzących, statystyk użycia ani automatycznego przesyłania raportów awarii. Obecne funkcje nie wymagają kontaktów, lokalizacji, aparatu, mikrofonu ani zdjęć i nie zbierają identyfikatorów reklamowych. System i sklepy mogą przetwarzać dane instalacyjne lub diagnostyczne według własnych zasad. Diagnostyka udostępniona twórcy służy wyłącznie rozwiązywaniu problemów.</p><h2 id="kontakt-i-usługi-zewnetrzne" tabindex="-1">Kontakt i usługi zewnętrzne <a class="header-anchor" href="#kontakt-i-usługi-zewnetrzne" aria-label="Permalink to &quot;Kontakt i usługi zewnętrzne&quot;">​</a></h2><p>Dobrowolny email przekazuje twórcy adres nadawcy, treść i załączniki do odpowiedzi, analizy problemu lub realizacji żądania dotyczącego prywatności, a nie do marketingu. Wysyłaj tylko potrzebne informacje. Gmail przetwarza pocztę zgodnie z <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">polityką Google</a>.</p><p>Witrynę obsługuje GitHub Pages, który może otrzymywać adres IP i dane techniczne przeglądarki; zobacz <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">politykę GitHub</a>. Nie dodano analityki odwiedzin, reklamowych plików cookie ani pikseli śledzących. Wyszukiwanie działa w przeglądarce, która może zapisywać preferencje. Zewnętrzne usługi mają własne zasady i mogą przetwarzać dane poza twoim krajem.</p><h2 id="wpłaty-i-kopie-zapasowe" tabindex="-1">Wpłaty i kopie zapasowe <a class="header-anchor" href="#wpłaty-i-kopie-zapasowe" aria-label="Permalink to &quot;Wpłaty i kopie zapasowe&quot;">​</a></h2><p>Alipay lub WeChat Pay obsługuje wpłaty na własnych warunkach. Witryna pokazuje tylko statyczne kody, bez SDK płatniczego i odbierania danych uwierzytelniających. Twórca może widzieć informacje przekazane odbiorcy przez platformę, np. kwotę, czas, wyświetlaną nazwę i notatkę, do rozliczenia wsparcia i obsługi problemów. Przechowywanie wynika z zasad platformy i obowiązujących wymogów. Dane aplikacji mogą trafić do kopii urządzenia lub chmury zależnie od ustawień; twórca nie może ich odczytać ani usunąć.</p><h2 id="udostepnianie-przechowywanie-i-usuwanie" tabindex="-1">Udostępnianie, przechowywanie i usuwanie <a class="header-anchor" href="#udostepnianie-przechowywanie-i-usuwanie" aria-label="Permalink to &quot;Udostępnianie, przechowywanie i usuwanie&quot;">​</a></h2><p>Twórca nie sprzedaje ani nie wynajmuje danych osobowych i nie udostępnia ich do reklam. Poczta jest przetwarzana przez wskazanego dostawcę. Rzeczywiście posiadane informacje mogą być przekazane, gdy wymaga tego prawo lub wyraźne żądanie użytkownika.</p><p>Dane lokalne usuwa się w aplikacji lub ustawieniach systemu. Odinstalowanie z zachowaniem danych ich nie usuwa; kopie zapasowe trzeba obsługiwać oddzielnie i mogą one przywrócić dane. Preferencje witryny pozostają do ich usunięcia lub automatycznego wyczyszczenia przez przeglądarkę. Wiadomości są przechowywane tylko na czas obsługi, dalszego kontaktu lub obowiązków prawnych. Dostawcy zarządzają własnymi dziennikami i kopiami. Aby uzyskać dostęp, poprawić lub usunąć wysłane dane, skontaktuj się z twórcą; obowiązki prawne mogą ograniczać usunięcie. Twórca nie ma zdalnego dostępu do danych pozostałych wyłącznie na urządzeniu.</p><h2 id="bezpieczenstwo-dzieci-i-zmiany" tabindex="-1">Bezpieczeństwo, dzieci i zmiany <a class="header-anchor" href="#bezpieczenstwo-dzieci-i-zmiany" aria-label="Permalink to &quot;Bezpieczeństwo, dzieci i zmiany&quot;">​</a></h2><p>Lokalne dane chronią mechanizmy systemu operacyjnego. Witryna używa HTTPS. Dostęp do wiadomości służy tylko pomocy i sprawom prywatności, z zabezpieczeniami dostawcy poczty. Aplikacja nie wymaga profilu ani daty urodzenia i nie zbiera świadomie danych dzieci. Opiekun może poprosić o usunięcie informacji przesłanych przez dziecko.</p><p>Polityka i data są aktualizowane przy zmianie praktyk, a istotne zmiany są ogłaszane na stronie lub przy aktualizacji aplikacji. Uprawnienia i zgody potrzebne nowym funkcjom są uzyskiwane oddzielnie; ta polityka ich nie zastępuje.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const u=e(r,[["render",t]]);export{w as __pageData,u as default};
